using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace MeridianStudio.Implementation.DefineTargetRegulationsAndDataSources
{
    public sealed record RegulationInfo(string Name, string Description, string Jurisdiction, DateTime EffectiveDate, DateTime? ExpiryDate);
    public sealed record DataSourceInfo(string Name, string Type, string ConnectionString, string SchemaDescription);
    public sealed record DefineRegulationsOptions
    {
        public List<RegulationInfo> TargetRegulations { get; init; } = new List<RegulationInfo>();
        public List<DataSourceInfo> DataSources { get; init; } = new List<DataSourceInfo>();
    }

    public interface IRegulationComplianceService
    {
        Task<IEnumerable<RegulationInfo>> GetTargetRegulationsAsync(CancellationToken cancellationToken = default);
        Task<IEnumerable<DataSourceInfo>> GetDataSourcesAsync(CancellationToken cancellationToken = default);
    }

    public sealed class RegulationComplianceService : IRegulationComplianceService
    {
        private readonly ILogger<RegulationComplianceService> _logger;
        private readonly IOptions<DefineRegulationsOptions> _options;

        public RegulationComplianceService(ILogger<RegulationComplianceService> logger, IOptions<DefineRegulationsOptions> options)
        {
            _logger = logger;
            _options = options;
            _logger.LogInformation("RegulationComplianceService initialized.");
        }

        public Task<IEnumerable<RegulationInfo>> GetTargetRegulationsAsync(CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            _logger.LogInformation("Retrieving target regulations.");
            return Task.FromResult(_options.Value.TargetRegulations.AsEnumerable());
        }

        public Task<IEnumerable<DataSourceInfo>> GetDataSourcesAsync(CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            _logger.LogInformation("Retrieving data sources.");
            return Task.FromResult(_options.Value.DataSources.AsEnumerable());
        }
    }

    public static class RegulationComplianceServiceCollectionExtensions
    {
        public static IServiceCollection AddRegulationComplianceService(this IServiceCollection services, Action<DefineRegulationsOptions> configureOptions)
        {
            services.Configure(configureOptions);
            services.AddSingleton<IRegulationComplianceService, RegulationComplianceService>();
            return services;
        }
    }
}
